sksl:
uniform shader image;
uniform float2 size;
uniform float time;

uniform float amount;
layout(color) uniform half4 shadowColor;
layout(color) uniform half4 highlightColor;

half4 main(float2 coord) {
    half4 c = image.eval(coord);
    half a = c.a;
    if (a < 0.001) {
        return half4(0.0);
    }
    half3 rgb = c.rgb / a;
    half lum = dot(rgb, half3(0.2126, 0.7152, 0.0722));
    half3 tint = mix(shadowColor.rgb, highlightColor.rgb, lum);
    half3 result = mix(rgb, tint, amount);
    return half4(result * a, a);
}
